<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {ElMessage} from 'element-plus';
import UiIcon from './UiIcon.vue';
import ReportReading from './ReportReading.vue';
import {api,categories,priceText,scenarioWeights} from './api';
import {drawReport,canvasBlob,loadReportImages} from './reportCanvas';
const props=defineProps({context:Object});
const initial=props.context.reportDocument?.version===2?props.context.reportDocument:null;
const category=ref(initial?.product.category||props.context.profile.category),budget=ref(initial?.profile.budget||props.context.profile.budget),scenario=ref(initial?.profile.scenario||props.context.profile.scenario||'办公'),needs=ref(initial?.profile.needs||props.context.profile.needs||'');
const pool=ref([]),selectedId=ref(initial?.product.id||props.context.selectedId),compareId=ref(initial?.peer?.id||props.context.comparePair?.find(p=>p.id!==selectedId.value)?.id||null),document=ref(initial),busy=ref(false),loading=ref(false),image=ref(''),theme=ref('violet'),format=ref('slide'),view=ref('reading'),exporting=ref(false),error=ref('');
const selected=computed(()=>pool.value.find(p=>p.id===selectedId.value));
let serial=0,generateSerial=0,renderSerial=0,disposed=false,currentBlob=null,reloadTimer,assets={};
function profile(){return {...props.context.profile,category:category.value,budget:budget.value,scenario:scenario.value,subcategory:null,needs:needs.value.trim()||'预算'+budget.value+'元，想选购'+category.value+'，用于'+scenario.value+'。',weights:scenario.value===props.context.profile.scenario?props.context.profile.weights:scenarioWeights(scenario.value)}}
function clearImage(){if(image.value)URL.revokeObjectURL(image.value);image.value='';currentBlob=null;}
function invalidate(){generateSerial++;renderSerial++;document.value=null;props.context.reportDocument=null;error.value='';busy.value=false;exporting.value=false;clearImage()}
async function preview(){if(!document.value)return false;const token=++renderSerial;exporting.value=true;clearImage();try{const blob=await canvasBlob(drawReport(document.value,theme.value,format.value,assets));if(token!==renderSerial||disposed)return false;currentBlob=blob;image.value=URL.createObjectURL(blob);return true}catch(e){if(token===renderSerial&&!disposed){error.value='图片生成未成功，网页报告仍可阅读。'+e.message;ElMessage.error(error.value)}return false}finally{if(token===renderSerial)exporting.value=false}}
async function load(){const token=++serial;loading.value=true;try{const result=await api('recommend',{...profile(),purpose:'report'});if(token!==serial||disposed)return;pool.value=result.products;if(!pool.value.some(p=>p.id===selectedId.value))selectedId.value=pool.value[0]?.id;if(!pool.value.some(p=>p.id===compareId.value&&p.id!==selectedId.value))compareId.value=pool.value.find(p=>p.recommendation_eligible&&p.id!==selectedId.value)?.id||null;await nextTick();if(props.context.autoReport){props.context.autoReport=false;await generate()}}catch(e){if(token===serial&&!disposed){error.value=e.message;ElMessage.error(e.message)}}finally{if(token===serial)loading.value=false}}
async function generate(){if(!selected.value)return;const token=++generateSerial;busy.value=true;error.value='';try{const payload=profile();const result=await api('report',{...payload,product_id:selectedId.value,compare_id:compareId.value||null});if(token!==generateSerial||disposed)return;if(!result.document)throw new Error(result.report||'报告未生成');document.value=result.document;props.context.reportDocument=result.document;props.context.selectedId=selectedId.value;Object.assign(props.context.profile,payload);assets=await loadReportImages(result.document);if(token!==generateSerial||disposed)return;await preview()}catch(e){if(token===generateSerial&&!disposed){error.value=e.message;ElMessage.error(e.message)}}finally{if(token===generateSerial)busy.value=false}}
async function download(){if(!document.value||exporting.value)return;if(!currentBlob&&!await preview())return;const link=window.document.createElement('a');link.href=image.value;link.download='SmartBuy-'+document.value.product.name.replace(/[\\/:*?"<>|]/g,'-')+'-'+(format.value==='slide'?'PPT精简版':'完整长图')+'.png';window.document.body.appendChild(link);link.click();link.remove()}
function categoryChanged(){needs.value='';selectedId.value=null;compareId.value=null;}
watch([category,budget,scenario,needs],()=>{invalidate();serial++;clearTimeout(reloadTimer);reloadTimer=setTimeout(load,350)});
watch(selectedId,(value,old)=>{if(old!=null&&value!==old)invalidate();if(compareId.value===value)compareId.value=pool.value.find(p=>p.recommendation_eligible&&p.id!==value)?.id||null});
watch(compareId,(value,old)=>{if(value!==old)invalidate()});watch([theme,format],()=>{if(document.value)preview()});
onMounted(async()=>{await load();if(document.value&&!image.value){assets=await loadReportImages(document.value);if(!disposed)await preview()}});onBeforeUnmount(()=>{disposed=true;serial++;generateSerial++;renderSerial++;clearTimeout(reloadTimer);clearImage()});
</script>
<template>
<section class="report-page report-v2"><div class="page-heading"><div><span class="eyebrow">YOUR NEXT GOOD CHOICE</span><h1>把选择，变成有依据的决定</h1><p>先看结论，再看取舍；把适合自己的理由与购买凭据一起留下。</p></div><span class="soft-label">网页阅读 · 16:9 简报 · 完整长图</span></div>
 <div class="report-layout"><aside class="report-controls panel"><div class="panel-caption"><h3>这次，想怎么选</h3><UiIcon name="report"/></div><p class="report-control-intro">围绕当前需求生成报告，预算与偏好沿用本次设置。</p><label>产品类别<el-select v-model="category" @change="categoryChanged"><el-option v-for="c in categories" :key="c" :label="c" :value="c"/></el-select></label><label>预算上限<el-input-number v-model="budget" :min="1" :max="50000" :step="100"/></label><label>主要用途<el-select v-model="scenario"><el-option v-for="s in ['老人使用','学习','办公','游戏']" :key="s" :label="s" :value="s"/></el-select></label><label>用途补充 <small>预算以上方为准</small><textarea v-model="needs" maxlength="1000" rows="3" placeholder="谁来使用？更在意什么？" aria-label="报告使用需求"></textarea></label><label>报告对象<el-select v-model="selectedId" filterable :loading="loading" placeholder="选择报告对象"><el-option v-for="p in pool" :key="p.id" :label="p.name" :value="p.id"/></el-select></label><label>另一款对比产品<el-select v-model="compareId" filterable clearable placeholder="可选：比较两款取舍"><el-option v-for="p in pool.filter(p=>p.id!==selectedId)" :key="p.id" :label="p.name" :value="p.id"/></el-select></label><div v-if="selected" class="report-product-summary"><small>{{selected.brand}} · {{selected.subcategory}}</small><h4>{{selected.name}}</h4><strong>{{priceText(selected)}}</strong><p>{{selected.budget_status}}</p></div><button class="primary-btn full-width" :disabled="busy||loading||!selected" @click="generate"><UiIcon name="spark" :size="17"/>{{busy?'整理依据中…':document?'重新生成报告':'生成选购报告'}}</button><p class="report-control-footnote">选择产品不等于系统推荐。待核价和超预算状态会如实写进报告。</p></aside>
 <div class="report-main"><div class="report-mode-bar"><div class="segmented"><button :class="{chosen:view==='reading'}" @click="view='reading'">网页阅读</button><button :class="{chosen:view==='image'}" @click="view='image'">图片预览</button></div><div class="report-export-options"><select v-model="format" aria-label="图片导出格式"><option value="slide">PPT 精简版 · 16:9</option><option value="full">完整长图 · 含全部来源</option></select><select v-model="theme" aria-label="报告配色"><option value="violet">暮光紫</option><option value="mint">薄荷绿</option></select><button class="primary-btn" :disabled="!document||busy||exporting" @click="download"><UiIcon name="download" :size="16"/>{{exporting?'生成图片中…':'保存 PNG'}}</button></div></div><p v-if="error" class="report-error" role="alert">{{error}}</p>
 <template v-if="document"><ReportReading v-if="view==='reading'" :document="document" :theme="theme"/><div v-else class="report-export-preview"><div class="report-export-caption"><b>{{format==='slide'?'一页，讲清这次选择':'详细依据，完整保留'}}</b><span>{{format==='slide'?'1920 × 1080 · 适合直接插入 PPT':'长图包含完整配置、报价条件与原始来源'}}</span></div><img v-if="image" :src="image" :alt="format==='slide'?'SmartBuy PPT精简版选购决策报告':'SmartBuy 完整选购报告长图'"/><div v-else class="report-export-wait">{{exporting?'正在排版图片…':'暂未生成图片，可重新生成或阅读网页报告。'}}</div><p>精简版压缩部分文字，完整参数、配置与来源可在网页和长图中查看。</p></div></template>
 <div v-else class="report-empty-state"><div class="report-empty-brand"><UiIcon name="report" :size="32"/></div><span class="eyebrow">A DECISION WORTH KEEPING</span><h2>这份报告，从你的需求开始。</h2><p>选好报告对象与对比产品，留下一份清楚、具体、可核对的选购结论。</p><div class="report-empty-outline"><article><b>01 / 结论</b><span>是否符合预算与本次需求</span></article><article><b>02 / 理由与取舍</b><span>为什么考虑，哪些还需确认</span></article><article><b>03 / 凭据与行动</b><span>报价从哪里来，下单前做什么</span></article></div><small>两种图片导出：PPT 精简版 / 完整长图</small></div>
 <div v-if="document" class="report-bottom-note">报告生成后可随时切换配色与导出格式，无需重复查询产品。报价与参数均保留各自的来源和采集日期。</div></div></div>
</section>
</template>
