 9px 27px #35224716}.report-export-preview>p{font-size:9px;color:#ad9db9;line-height:1.8;margin:18px 0 0}.report-export-wait{display:grid;place-items:center;min-height:420px;background:#f8f5fc;border-radius:9px;font-size:12px;color:#b29bc3}.report-error{background:#fff4e9;color:#ac835e;border:1px solid #f0ddc6;padding:13px 17px;border-radius:8px;font-size:11px;line-height:1.8}.report-empty-state{background:linear-gradient(130deg,#f7f2fc,#fff 55%,#faf5ec);border:1px solid #e8e0f0;min-height:680px;padding:64px 38px;border-radius:17px;text-align:center}.report-empty-brand{height:80px;width:80px;display:grid;place-items:center;border-radius:23px;background:#eee5f9;color:#ae90d1;margin:0 auto 33px}.report-empty-state h2{font-size:27px;font-weight:500;color:#907a9e;margin:22px 0}.report-empty-state>p{font-size:12px;line-height:2;color:#b19ebc;max-width:440px;margin:0 auto}.report-empty-outline{display:flex;flex-direction:column;gap:13px;max-width:390px;margin:37px auto 30px;text-align:left}.report-empty-outline article{border:1px solid #ebe3f4;border-radius:9px;display:flex;align-items:center;gap:20px;padding:17px 20px;background:#ffffffb0}.report-empty-outline b{font-size:11px;font-weight:500;color:#a18ab7}.report-empty-outline span{font-size:10px;color:#b8a7c2}.report-empty-state>small{font-size:9px;color:#bbadca}.report-bottom-note{font-size:9px;color:#ac9cb8;text-align:center;line-height:1.9;padding:18px 8px}
