@media(max-width:900px){.report-v2 .report-layout{grid-template-columns:1fr}.report-v2 .report-controls{position:static;max-height:none;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 20px}.report-controls>.panel-caption,.report-control-intro,.report-control-footnote{grid-column:1/-1}.report-v2 .report-controls label{min-width:0}.report-v2 .report-controls>.primary-btn{align-self:center;max-width:none}.report-empty-state{min-height:550px}.report-empty-state h2{font-size:23px}}
@media(max-width:540px){.report-v2 .report-controls{gap:0 12px}.report-controls textarea{font-size:10px}.report-empty-state{padding:40px 22px}.report-empty-outline article{padding:14px;gap:12px}.report-export-options{gap:6px}.report-export-options select{max-width:160px;font-size:9px}.report-export-preview{padding:15px}.report-empty-state h2{font-size:20px}}
